//! Compresses the command-signature JSON into one blob that `src/assets.rs` embeds.
//!
//! The specs are about 30 MB of pretty-printed JSON; each file is deflated on its own so a
//! lookup only inflates the one signature it needs (they are loaded lazily, per command).

use std::fmt::Write as _;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::{env, fs};

use flate2::write::DeflateEncoder;
use flate2::Compression;

/// Returns the `.json` files directly inside `dir`, sorted by file name.
fn json_files(dir: &Path) -> Vec<(String, PathBuf)> {
    let mut files: Vec<_> = fs::read_dir(dir)
        .unwrap_or_else(|err| panic!("couldn't read {}: {err}", dir.display()))
        .map(|entry| entry.expect("couldn't read directory entry").path())
        .filter(|path| path.is_file() && path.extension().is_some_and(|ext| ext == "json"))
        .map(|path| {
            let name = path
                .file_name()
                .and_then(|name| name.to_str())
                .expect("signature file names are UTF-8")
                .to_owned();
            (name, path)
        })
        .collect();
    files.sort();
    files
}

/// Appends each file's deflated bytes to `blob` and returns a Rust slice expression of
/// `(name, offset, len)` entries, sorted by name for binary search.
fn compress_into(blob: &mut Vec<u8>, files: &[(String, PathBuf)]) -> String {
    let mut table = String::from("&[\n");
    for (name, path) in files {
        let json = fs::read(path).unwrap_or_else(|err| panic!("couldn't read {}: {err}", path.display()));
        let mut encoder = DeflateEncoder::new(Vec::new(), Compression::best());
        encoder.write_all(&json).expect("deflating to memory can't fail");
        let compressed = encoder.finish().expect("deflating to memory can't fail");
        writeln!(table, "    ({name:?}, {}, {}),", blob.len(), compressed.len()).unwrap();
        blob.extend_from_slice(&compressed);
    }
    table.push(']');
    table
}

fn main() {
    let out_dir = PathBuf::from(env::var_os("OUT_DIR").expect("cargo sets OUT_DIR"));
    let json_dir = Path::new("json");
    println!("cargo:rerun-if-changed=json");
    println!("cargo:rerun-if-changed=json/autogenerated/powershell");

    let mut blob = Vec::new();
    let mut index = String::new();
    // Hand-written specs (json/*.json) first, then the autogenerated PowerShell ones; a name
    // in both resolves to the hand-written spec, as it did with the two rust-embed folders.
    if env::var_os("CARGO_FEATURE_EMBED_SIGNATURES").is_some() {
        let manual = compress_into(&mut blob, &json_files(json_dir));
        let powershell = compress_into(
            &mut blob,
            &json_files(&json_dir.join("autogenerated").join("powershell")),
        );
        writeln!(index, "pub(super) static MANUAL: &[(&str, usize, usize)] = {manual};").unwrap();
        writeln!(index, "pub(super) static POWERSHELL: &[(&str, usize, usize)] = {powershell};").unwrap();
    }

    fs::write(out_dir.join("signatures.deflate"), blob).expect("couldn't write signatures.deflate");
    fs::write(out_dir.join("signatures_index.rs"), index).expect("couldn't write signatures_index.rs");
}
